import{_ as a,C as r,o,c as h,aj as d,E as n}from"./framework.js";const _=JSON.parse('{"title":"控制台：订单 | Product / Console | Documentation","description":"控制台：订单 in Kooboo: 订单页显示当前组织的订单记录。域名购买、域名续费、会员购买、充值等流程都会创建订单。","frontmatter":{"title":"控制台：订单 | Product / Console | Documentation","description":"控制台：订单 in Kooboo: 订单页显示当前组织的订单记录。域名购买、域名续费、会员购买、充值等流程都会创建订单。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/console/orders.html"}]]},"headers":[],"relativePath":"zh/product/console/orders.md","filePath":"product/console/orders.md","lastUpdated":1781010536000}'),l={name:"zh/product/console/orders.md"};function c(s,t,i,b,p,m){const e=r("DocImage");return o(),h("div",null,[t[0]||(t[0]=d('<h1 id="控制台-订单" tabindex="-1">控制台：订单 <a class="header-anchor" href="#控制台-订单" aria-label="Permalink to &quot;控制台：订单&quot;">​</a></h1><blockquote><p>查看当前组织订单，继续支付未完成订单，并在结账页选择支付方式。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>控制台</strong> -&gt; 左侧 <strong>订单</strong></td></tr><tr><td>订单列表深链</td><td><code>/_Admin/kconsole/consoleOrder</code></td></tr><tr><td>结账页深链</td><td><code>/_Admin/kconsole/checkOrder?orderId={orderId}</code></td></tr><tr><td>前端路由</td><td><code>/kconsole/consoleOrder</code>、<code>/kconsole/checkOrder</code></td></tr><tr><td>可见身份</td><td>组织管理员</td></tr></tbody></table><p>订单页显示当前组织的订单记录。域名购买、域名续费、会员购买、充值等流程都会创建订单。</p>',5)),n(e,{src:"/product/console/orders-overview.png",alt:"控制台订单列表（金额与域名已脱敏）",width:"1120"}),t[1]||(t[1]=d('<h2 id="订单列表" tabindex="-1">订单列表 <a class="header-anchor" href="#订单列表" aria-label="Permalink to &quot;订单列表&quot;">​</a></h2><p>页面顶部会显示订单提示和不可退款提醒。下面的表格显示：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Line Title</td><td>订单标题</td></tr><tr><td>Total Amount</td><td>订单总金额与币种</td></tr><tr><td>Date</td><td>创建时间</td></tr><tr><td>Type</td><td>订单类型</td></tr><tr><td>Is Paid</td><td>是否已支付</td></tr><tr><td>Is Delivered</td><td>是否已交付</td></tr><tr><td>Pay</td><td>未支付且可支付的订单显示该按钮</td></tr></tbody></table><p>订单类型标签包括购买、会员、带宽、服务、服务器、充值、API 市场、应用市场、续费等。</p><p>点击 <code>Pay</code> 会进入结账页：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/kconsole/checkOrder?orderId={orderId}</span></span></code></pre></div><h2 id="结账页" tabindex="-1">结账页 <a class="header-anchor" href="#结账页" aria-label="Permalink to &quot;结账页&quot;">​</a></h2><p>结账页左侧是订单摘要与支付方式，右侧是订单金额汇总。</p><p>左侧主要区域：</p><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>订单标题与 Summary</td><td>显示订单说明</td></tr><tr><td>Payment Method</td><td><code>Credit Card</code>、<code>Wechat Pay</code> 两个 Tab</td></tr><tr><td>已保存信用卡</td><td>显示卡尾号，可直接选择</td></tr><tr><td>新增信用卡</td><td>点击加号后填写卡信息</td></tr><tr><td>微信支付二维码</td><td>切换到 <code>Wechat Pay</code> 后生成二维码并轮询支付状态</td></tr></tbody></table><p>右侧金额汇总：</p><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>Order Summary</td><td>订单明细项</td></tr><tr><td>Subtotal</td><td>小计</td></tr><tr><td>VAT</td><td>税费</td></tr><tr><td>Total</td><td>总额与币种</td></tr><tr><td>Submit Payment / Scan To Pay</td><td>提交信用卡支付，或提示扫码支付</td></tr></tbody></table><h2 id="信用卡支付" tabindex="-1">信用卡支付 <a class="header-anchor" href="#信用卡支付" aria-label="Permalink to &quot;信用卡支付&quot;">​</a></h2><p>如果选择已有信用卡，直接点击 <code>Submit Payment</code>。</p><p>如果新增信用卡，需要填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Card Number</td><td>卡号</td></tr><tr><td>Expiration Date</td><td>月份与年份</td></tr><tr><td>Name on Card</td><td>持卡人姓名</td></tr><tr><td>CVC</td><td>安全码</td></tr></tbody></table><p>提交后如果后端返回跳转地址，页面会跳转到该地址继续支付；如果支付成功且无需跳转，会回到订单列表。</p><h2 id="微信支付" tabindex="-1">微信支付 <a class="header-anchor" href="#微信支付" aria-label="Permalink to &quot;微信支付&quot;">​</a></h2><p>切换到 <code>Wechat Pay</code> 后，页面会生成二维码并每秒检查支付状态。支付完成后会自动回到订单列表。</p><p>如果二维码一直没有变化或支付后没有跳转，先检查订单是否仍在订单列表中显示未支付，再重新进入结账页。</p><h2 id="常见工作流" tabindex="-1">常见工作流 <a class="header-anchor" href="#常见工作流" aria-label="Permalink to &quot;常见工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>继续支付未完成订单</td><td>订单 -&gt; Pay -&gt; 结账页</td></tr><tr><td>域名购买后付款</td><td><a href="./domains.html#购买域名">域名购买</a> -&gt; 结账页 -&gt; 订单列表核对</td></tr><tr><td>充值后付款</td><td><a href="./balance.html#充值">余额</a> -&gt; 结账页 -&gt; 余额页核对</td></tr><tr><td>会员购买后付款</td><td><a href="./membership.html">会员</a> -&gt; 结账页 -&gt; 会员页核对</td></tr></tbody></table><h2 id="与余额、续费的关系" tabindex="-1">与余额、续费的关系 <a class="header-anchor" href="#与余额、续费的关系" aria-label="Permalink to &quot;与余额、续费的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>负责什么</th></tr></thead><tbody><tr><td><a href="./balance.html">余额</a></td><td>发起充值、查看收支记录</td></tr><tr><td>订单</td><td>查看订单和支付状态</td></tr><tr><td><a href="./renewals.html">续费</a></td><td>找到即将到期或已到期项目，并创建续费订单</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../console.html">控制台概述</a></td><td>控制台菜单地图</td></tr><tr><td><a href="./balance.html">余额</a></td><td>充值入口</td></tr><tr><td><a href="./renewals.html">续费</a></td><td>续费入口</td></tr></tbody></table>',26))])}const y=a(l,[["render",c]]);export{_ as __pageData,y as default};
